const fs = require('fs');
const path = require('path');
const encoded = "";
const content = Buffer.from(encoded, 'base64').toString('utf-8');
const outPath = path.join(process.env.USERPROFILE, 'psle-app', 'src', 'components', 'GeniusAdaptiveEngine.jsx');
fs.writeFileSync(outPath, content, 'utf8');
const stats = fs.statSync(outPath);
console.log('Done! ' + stats.size + ' bytes');
